using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Ryujinx.Graphics.Gpu;
using Ryujinx.Memory;

// Plan 748 rank 11 (adapt_device_critical_trim) on the final preparation: GpuContext's text from TrimMiB to the end of
// CheckHostMemory (TrimCaches, the periodic trim and its escalation, with their constants and fields) is compiled unchanged
// into GpuContextUnderTest (Trim.cs, generated by the test). Doubles: HostMemoryBudget, the host clock (the production
// Environment.TickCount64 binds to Ryujinx.Graphics.Gpu.Environment below before System's), the logger, GraphicsConfig,
// the cold texture release and memory inventory members CheckHostMemory calls, and one PhysicalMemory whose caches record
// each trim call with the texture cache's OnlyUnreferencedTrim flag as it is when they are called.
namespace Ryujinx.Memory
{
    public enum MemoryPressureLevel { Normal = 0, Warning = 1, Critical = 2 }

    public static class HostMemoryBudget
    {
        public static ulong AvailableBytes;
        public static int DeviceAvailablePercent;
        public static bool IsConstrained => true;
        public static ulong FootprintBytes => 4814UL << 20;
    }
}

namespace Ryujinx.Common.Logging
{
    public enum LogClass { Gpu }

    public struct Printer
    {
        public void Print(LogClass logClass, string message) => Logger.Lines.Add(message);
    }

    public static class Logger
    {
        public static readonly List<string> Lines = new();
        public static Printer? Debug = new Printer();
        public static Printer? Info = new Printer();
    }
}

namespace Ryujinx.Graphics.Gpu.Image
{
    public static class AutoDeleteCache
    {
        [ThreadStatic]
        internal static bool OnlyUnreferencedTrim;
        public const int MaxRetainedEntries = 1024;
        public const ulong MaxRetainedBytes = 32UL << 20;
        public const long MaxRetainedTicks = 60;
    }

    public struct ShortCacheReuseStats
    {
        public int Retained;
        public ulong RetainedBytes, PeakRetainedBytes;
        public long Reused, ReleasedByAge, RefusedByBound, ReleasedAll, ReleasedInvalid, DestroyedOnExpiry;
        public void Add(in ShortCacheReuseStats other) { }
    }
}

namespace Ryujinx.Graphics.Gpu
{
    public static class Clock
    {
        public static long Now = 1_000_000;
    }

    // The production text reads Environment.TickCount64: inside this namespace it binds here.
    public static class Environment
    {
        public static long TickCount64 => Clock.Now;
    }

    public static class GraphicsConfig
    {
        public static bool EnableHostMemoryBudgetTracking = true;
    }

    public sealed class TextureCacheDouble
    {
        public readonly List<string> Calls = new();
        public bool Throw;
        public ulong Trim(MemoryPressureLevel level, bool freeOnly = false)
        {
            Calls.Add($"textures {level} freeOnly={freeOnly} onlyUnreferenced={Image.AutoDeleteCache.OnlyUnreferencedTrim}");
            if (Throw) throw new InvalidOperationException("texture trim");
            return 32UL << 20;
        }
        public ulong LastTrimKeptBytes => 16UL << 20;
        public ulong CachedBytes => 155UL << 20;
        public ulong CacheLimit => 768UL << 20;
        public Image.ShortCacheReuseStats ShortCacheReuse => default;
    }

    public sealed class BufferCacheDouble
    {
        public readonly List<string> Calls = new();
        public ulong Trim(MemoryPressureLevel level, bool byCapacity = false)
        {
            Calls.Add($"buffers {level} byCapacity={byCapacity}");
            return 8UL << 20;
        }
        public ulong CachedBytes => 184UL << 20;
        public ulong CacheLimit => 554UL << 20;
    }

    public sealed class PhysicalMemory
    {
        public readonly TextureCacheDouble TextureCache = new();
        public readonly BufferCacheDouble BufferCache = new();
    }

    public partial class GpuContextUnderTest
    {
        internal ConcurrentDictionary<ulong, PhysicalMemory> PhysicalMemoryRegistry { get; } = new();

        // What CheckHostMemory calls besides the trim (adapt_cold_texture_release, adapt_memory_inventory): doubles.
        internal struct ColdTextureStats
        {
            public int PoolOnly, GpuData, Cold;
            public ulong PoolOnlyBytes, GpuDataBytes, ColdBytes;
        }

        internal int TextureUseEpoch;
        private int _coldTextureAgeSeconds = 60;
        private long _coldReleasedTotal;
        private ulong _coldReleasedBytesTotal;
        public int ColdPasses, Reports;

        internal bool ReleaseColdTextures(int device, long now, out ColdTextureStats stats)
        {
            stats = default;
            ColdPasses++;
            return false;
        }

        internal ColdTextureStats MeasurePoolTextures(out int reloads, out int pinned)
        {
            reloads = pinned = 0;
            return default;
        }

        private void RecordMemoryInventory(int device, ulong textures, ulong textureLimit, ulong buffers, ulong bufferLimit) => Reports++;
    }
}

static class Program
{
    const ulong MiB = 1024 * 1024;

    static string Calls(PhysicalMemory memory, int from = 0, int bufferFrom = 0) =>
        string.Join("; ", memory.TextureCache.Calls.Skip(from)) + " | " + string.Join("; ", memory.BufferCache.Calls.Skip(bufferFrom));

    // One host report (TrimCaches from Switch.ProcessFrame), or an escalated call, on a fresh context.
    static Dictionary<string, object> Report(MemoryPressureLevel level, ulong available, int device, bool escalated)
    {
        HostMemoryBudget.AvailableBytes = available;
        HostMemoryBudget.DeviceAvailablePercent = device;
        Ryujinx.Common.Logging.Logger.Lines.Clear();
        var context = new GpuContextUnderTest();
        var memory = new PhysicalMemory();
        context.PhysicalMemoryRegistry[1] = memory;
        if (escalated) context.TrimCaches(level, escalated: true); else context.TrimCaches(level);
        bool flagAfter = Ryujinx.Graphics.Gpu.Image.AutoDeleteCache.OnlyUnreferencedTrim;
        int before = memory.TextureCache.Calls.Count;
        context.TrimCaches(level, escalated);
        return new()
        {
            ["level"] = level.ToString(),
            ["availableMiB"] = available / MiB,
            ["device"] = device,
            ["escalated"] = escalated,
            ["calls"] = Calls(memory),
            ["flagAfter"] = flagAfter,
            ["secondWithin2s"] = memory.TextureCache.Calls.Count - before,
            ["log"] = string.Join(" / ", Ryujinx.Common.Logging.Logger.Lines),
        };
    }

    // CheckHostMemory once a second (the frame loop), the device's share per second from `device`; `pauseAfter`: a host
    // pause of that many seconds after that second (no check). Returns each trim: second, calls and its log line.
    static Dictionary<string, object> Timeline(ulong available, Func<int, int> device, int seconds, int pauseAfter = 0, int pauseSeconds = 0)
    {
        HostMemoryBudget.AvailableBytes = available;
        Clock.Now = 1_000_000;
        Ryujinx.Common.Logging.Logger.Lines.Clear();
        var context = new GpuContextUnderTest();
        var memory = new PhysicalMemory();
        context.PhysicalMemoryRegistry[1] = memory;
        var trims = new List<object>();
        for (int second = 1; second <= seconds; second++)
        {
            Clock.Now += 1000;
            HostMemoryBudget.DeviceAvailablePercent = device(second);
            int textures = memory.TextureCache.Calls.Count, buffers = memory.BufferCache.Calls.Count, lines = Ryujinx.Common.Logging.Logger.Lines.Count;
            context.CheckHostMemory();
            if (memory.TextureCache.Calls.Count != textures)
            {
                string line = Ryujinx.Common.Logging.Logger.Lines.Skip(lines).FirstOrDefault(l => l.StartsWith("Host reported")) ?? "";
                trims.Add(new Dictionary<string, object> { ["second"] = second, ["calls"] = Calls(memory, textures, buffers), ["log"] = line });
            }
            if (Ryujinx.Graphics.Gpu.Image.AutoDeleteCache.OnlyUnreferencedTrim) throw new Exception("flag left set after a check");
            if (second == pauseAfter) Clock.Now += 1000L * pauseSeconds;
        }
        return new() { ["trims"] = trims, ["coldPasses"] = context.ColdPasses, ["reports"] = context.Reports, ["epoch"] = context.TextureUseEpoch };
    }

    static int Main()
    {
        var output = new Dictionary<string, object>();
        var reports = new List<Dictionary<string, object>>();
        var cases = new List<(MemoryPressureLevel level, ulong available, int device, bool escalated)>
        {
            // The table of the delivered fixture (host reports), first.
            (MemoryPressureLevel.Warning, 2102 * MiB, 11, false),
            (MemoryPressureLevel.Warning, 2102 * MiB, 8, false),
            (MemoryPressureLevel.Warning, 2102 * MiB, 12, false),
            (MemoryPressureLevel.Warning, 2102 * MiB, 13, false),
            (MemoryPressureLevel.Warning, 2102 * MiB, 27, false),
            (MemoryPressureLevel.Warning, 2375 * MiB, 7, false),
            (MemoryPressureLevel.Warning, 2102 * MiB, -1, false),
            (MemoryPressureLevel.Warning, 700 * MiB, 11, false),
            (MemoryPressureLevel.Warning, 200 * MiB, 30, false),
            (MemoryPressureLevel.Critical, 2102 * MiB, 11, false),
            (MemoryPressureLevel.Normal, 2102 * MiB, 5, false),
            // pid 12613's Critical (05:00:39, dispatch source): 2 086 MiB of headroom, device 5 %.
            (MemoryPressureLevel.Critical, 2086 * MiB, 5, false),
            (MemoryPressureLevel.Critical, 2102 * MiB, 13, false),
            (MemoryPressureLevel.Critical, 700 * MiB, 5, false),
            (MemoryPressureLevel.Critical, 0, 5, false),
            (MemoryPressureLevel.Warning, 2102 * MiB, 5, true),
            (MemoryPressureLevel.Warning, 700 * MiB, 5, true),
            (MemoryPressureLevel.Warning, 2102 * MiB, 13, true),
        };
        foreach (var (level, available, device, escalated) in cases)
        {
            reports.Add(Report(level, available, device, escalated));
        }
        output["reports"] = reports;

        // A texture trim that throws: the flag is cleared all the same.
        {
            HostMemoryBudget.AvailableBytes = 2102 * MiB;
            HostMemoryBudget.DeviceAvailablePercent = 5;
            var context = new GpuContextUnderTest();
            var memory = new PhysicalMemory();
            memory.TextureCache.Throw = true;
            context.PhysicalMemoryRegistry[1] = memory;
            string thrown = "";
            try { context.TrimCaches(MemoryPressureLevel.Critical); } catch (InvalidOperationException e) { thrown = e.Message; }
            output["throwing"] = new Dictionary<string, object>
            {
                ["thrown"] = thrown,
                ["calls"] = Calls(memory),
                ["flagAfter"] = Ryujinx.Graphics.Gpu.Image.AutoDeleteCache.OnlyUnreferencedTrim,
            };
        }

        // Escalation: 8 % for 9 s, then 5 % (6 % at second 75), 3 % at second 120.
        output["escalation"] = Timeline(2102 * MiB, s => s < 10 ? 8 : s == 75 ? 6 : s == 120 ? 3 : 5, 125);
        // A host pause of 300 s after second 20, at 5 % throughout: it counts as two seconds of play at most.
        output["pause"] = Timeline(2102 * MiB, s => 5, 45, pauseAfter: 20, pauseSeconds: 300);
        // An unknown reading (-1) at second 26 ends the run.
        output["unknownReading"] = Timeline(2102 * MiB, s => s == 26 ? -1 : 5, 65);
        // This process's own pressure: the escalated trim is the delivered full trim.
        output["ownPressure"] = Timeline(500 * MiB, s => 5, 45);
        // 6-7 %: periodic trims, never escalated.
        output["sixPercent"] = Timeline(2102 * MiB, s => 6, 95);

        Console.WriteLine(JsonSerializer.Serialize(output));
        return 0;
    }
}
